/**
 * Formats the browser tab title as `<page title> – <site title>`. The site title falls back to the
 * package name, matching the HTML shell generated by Vited Core.
 */
export function formatDocumentTitle(
  pageTitle: string,
  siteTitle: string,
  packageJSON: Record<string, unknown> = {},
): string {
  const name = siteTitle || (typeof packageJSON['name'] === 'string' ? packageJSON['name'] : '');
  if (!pageTitle) return name;
  if (!name || pageTitle === name) return pageTitle;
  return `${pageTitle} – ${name}`;
}
